    }
    div = (div + 1) & 0xffff;
    const c = curAnd();
    if (prevAnd === 1 && c === 0) {
      if (reload === 0) incTima();
    }
    prevAnd = c;
  }

  function peek(a: number): number {
    a &= 0xffff;
    if (a < 0x8000) return cart.read(a);
    if (a < 0xa000) {
      return ppu.vram[a - 0x8000] & 0xff;
    }
    if (a < 0xc000) return cart.readRam(a);
    if (a < 0xe000) return wram[a - 0xc000] & 0xff;
    if (a < 0xfe00) return wram[a - 0xe000] & 0xff;
